ALTER TABLE public.internal_messages ADD COLUMN attachments jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN contact_card jsonb;
CREATE OR REPLACE FUNCTION public.chat_sheet_access(_sheet uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.job_sheets s WHERE s.id=_sheet AND s.company_id=public.current_company_id() AND (public.is_company_manager() OR s.assigned_technician_id=auth.uid() OR EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=s.job_id AND j.company_id=s.company_id AND (j.secondary_technician_id=auth.uid() OR j.assigned_technician_id=auth.uid() OR EXISTS(SELECT 1 FROM public.job_crew c WHERE c.job_id=j.id AND c.user_id=auth.uid()))))); $$;
REVOKE ALL ON FUNCTION public.chat_sheet_access(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.chat_sheet_access(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.can_read_chat_object(_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.member_is_active(auth.uid()) AND public.company_module_access(public.current_company_id(),'core') AND split_part(_name,'/',1)=public.current_company_id()::text AND (split_part(_name,'/',2)=auth.uid()::text OR EXISTS(SELECT 1 FROM public.internal_messages m WHERE m.company_id=public.current_company_id() AND EXISTS(SELECT 1 FROM jsonb_array_elements(m.attachments) a WHERE a->>'path'=_name) AND (m.sender_id=auth.uid() OR m.receiver_id=auth.uid() OR (m.receiver_id IS NULL AND public.chat_sheet_access(m.job_sheet_id))))); $$;
REVOKE ALL ON FUNCTION public.can_read_chat_object(text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.can_read_chat_object(text) TO authenticated;
CREATE POLICY chat_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='chat-attachments' AND (storage.foldername(name))[1]=public.current_company_id()::text AND (storage.foldername(name))[2]=auth.uid()::text AND public.member_is_active(auth.uid()) AND public.company_module_access(public.current_company_id(),'core'));
CREATE POLICY chat_download ON storage.objects FOR SELECT TO authenticated USING(bucket_id='chat-attachments' AND public.can_read_chat_object(name));
CREATE POLICY chat_discard_unsent ON storage.objects FOR DELETE TO authenticated USING(bucket_id='chat-attachments' AND (storage.foldername(name))[1]=public.current_company_id()::text AND (storage.foldername(name))[2]=auth.uid()::text AND public.member_is_active(auth.uid()) AND public.company_module_access(public.current_company_id(),'core') AND NOT EXISTS(SELECT 1 FROM public.internal_messages m WHERE m.attachments @> jsonb_build_array(jsonb_build_object('path',name))));
CREATE POLICY chat_thread_boundary ON public.internal_messages AS RESTRICTIVE FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'core') AND (sender_id=auth.uid() OR receiver_id=auth.uid() OR (receiver_id IS NULL AND public.chat_sheet_access(job_sheet_id))));
CREATE OR REPLACE FUNCTION public.guard_chat_payload() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,storage AS $$ DECLARE a jsonb; p text; BEGIN
IF NEW.company_id IS DISTINCT FROM public.current_company_id() OR NEW.sender_id IS DISTINCT FROM auth.uid() OR NOT public.member_is_active(auth.uid()) OR NOT public.company_module_access(NEW.company_id,'core') THEN RAISE EXCEPTION 'Chat access required';END IF;
IF NEW.receiver_id IS NULL AND NEW.job_sheet_id IS NULL THEN RAISE EXCEPTION 'Choose a conversation';END IF;
IF NEW.receiver_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.users WHERE id=NEW.receiver_id AND company_id=NEW.company_id AND public.member_is_active(id)) THEN RAISE EXCEPTION 'Choose an active company colleague';END IF;
IF NEW.job_sheet_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.job_sheets s WHERE s.id=NEW.job_sheet_id AND s.company_id=NEW.company_id AND (NEW.receiver_id IS NOT NULL OR public.chat_sheet_access(s.id))) THEN RAISE EXCEPTION 'Job conversation unavailable';END IF;
IF jsonb_typeof(NEW.attachments)<>'array' OR jsonb_array_length(NEW.attachments)>5 OR length(NEW.message_text)>4000 OR (trim(NEW.message_text)='' AND NEW.attachments='[]'::jsonb AND NEW.contact_card IS NULL) THEN RAISE EXCEPTION 'Message is empty or too large';END IF;
FOR a IN SELECT * FROM jsonb_array_elements(NEW.attachments) LOOP p=a->>'path';
IF jsonb_typeof(a)<>'object' OR length(coalesce(a->>'name','')) NOT BETWEEN 1 AND 180 OR coalesce((a->>'size')::bigint,0) NOT BETWEEN 1 AND 20971520 OR coalesce(a->>'type','') NOT IN('image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf','text/plain','text/csv','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') OR coalesce(split_part(p,'/',1),'')<>NEW.company_id::text OR coalesce(split_part(p,'/',2),'')<>auth.uid()::text OR coalesce(p,'') !~ '^[a-f0-9-]+/[a-f0-9-]+/[a-f0-9-]+\.[a-z0-9]+$' OR NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='chat-attachments' AND o.name=p AND (o.metadata->>'size')::bigint=(a->>'size')::bigint AND o.metadata->>'mimetype'=a->>'type') THEN RAISE EXCEPTION 'Invalid or unavailable attachment';END IF;END LOOP;
IF NEW.contact_card IS NOT NULL THEN IF jsonb_typeof(NEW.contact_card)<>'object' OR length(coalesce(NEW.contact_card->>'name','')) NOT BETWEEN 1 AND 100 OR length(coalesce(NEW.contact_card->>'phone',''))>50 OR length(coalesce(NEW.contact_card->>'email',''))>150 OR length(coalesce(NEW.contact_card->>'company',''))>100 OR (coalesce(NEW.contact_card->>'phone','')='' AND coalesce(NEW.contact_card->>'email','')='') OR NEW.contact_card - ARRAY['name','phone','email','company'] <> '{}'::jsonb THEN RAISE EXCEPTION 'Invalid contact card';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER chat_payload_guard BEFORE INSERT ON public.internal_messages FOR EACH ROW EXECUTE FUNCTION public.guard_chat_payload();